let state=ShopEngine.blankState();let choice={quantities:products.map(p=>p[4]),price:'list',action:'tend',payment:'cash'};let lastReport=null;let tab='bs';let sceneTimer;let seenEntries=new Set();let animationQueue=[];let animationReturn=null;let introComplete=false;let financialMode="month";let financialYear=1;let monthClosed=false;let statementReport=null;let reportFocus=null;
const el=id=>document.getElementById(id),fmt=n=>`${Math.round(n/1000).toLocaleString('ja-JP')}千円`,signed=n=>`${n>=0?'+':'△'}${fmt(Math.abs(n))}`,month=t=>((t+2)%12)+1,fy=t=>Math.floor((t-1)/12)+1;const cash=()=>state.balances.預金;
function journal(b,entries,debit,credit,amount,memo){if(!Number.isInteger(amount)||amount<0)throw Error('仕訳金額');if(amount===0)return;const before={...b};b[debit]=(b[debit]||0)+(debitAccounts.includes(debit)?amount:-amount);b[credit]=(b[credit]||0)+(creditAccounts.includes(credit)?amount:-amount);entries.push({debit,credit,amount,memo,before,after:{...b}});}
function orderCost(){return products.reduce((s,p,i)=>s+choice.quantities[i]*p[1],0)}
function renderOrders(){el('orders').innerHTML=products.map((p,i)=>`<div class="product-order"><div class="product-title"><span aria-hidden="true">${['🪝','🪱','🎣'][i]}</span><div><b>${p[0]}</b><small>在庫 ${state.inventory[i].toLocaleString('ja-JP')}${i===2?'本':'個'} · 仕入単価 ${(p[1]/1000).toFixed(2)}千円</small></div></div><div class="order-controls"><button type="button" data-product="${i}" data-step="-${i===2?5:50}" aria-label="${p[0]}を減らす">−</button><input id="quantity-${i}" data-product="${i}" type="number" inputmode="numeric" min="0" max="${i===2?300:4000}" step="1" value="${choice.quantities[i]}" aria-label="${p[0]}の仕入数量"><button type="button" data-product="${i}" data-step="${i===2?5:50}" aria-label="${p[0]}を増やす">＋</button><b>${fmt(choice.quantities[i]*p[1])}</b></div></div>`).join('');el('orderTotal').textContent=fmt(orderCost())}
function setQuantity(i,value){choice.quantities[i]=Math.min(i===2?300:4000,Math.max(0,Math.floor(Number(value)||0)));renderPlanning()}

function actionCost(){return choice.action==='sales'?200000:choice.action==='fixture'&&!state.fixture?1000000:0}
function animateScene(){const sc=el('scene');sc.className='scene';void sc.offsetWidth;sc.classList.add('stocked');if(choice.price==='sale')sc.classList.add('sale');if(choice.action==='tend')sc.classList.add('busy');else sc.classList.add('owner-away');if(choice.action==='sales'||choice.action==='fixture')sc.classList.add('event');let phrase=choice.action==='tend'?'社長が店頭で接客中':choice.action==='sales'?'釣り大会の協賛へ。店番はお休み':'新しい什器を搬入。店番はお休み';if(choice.action==='fixture'&&state.fixture)phrase='什器は購入済み。社長は店外で設備を確認中';el('sceneActivity').textContent=`${choice.quantities.filter(n=>n>0).length}種類の商品を仕入れ → ${phrase}`;clearTimeout(sceneTimer);sceneTimer=setTimeout(()=>{sc.classList.add('selling');el('sceneActivity').textContent=choice.action==='tend'?'クエ１人で開店！接客中':'今月は休業 · 店番がいないため販売なし';if(choice.action!=='tend')sc.classList.remove('selling');},900)}
function renderPlanning(){renderPersonal();el('staffAdvice').textContent=choice.action==='tend'?'従業員０人。今月はクエ１人で店番をします。':'従業員０人のため、社長が外出する今月は休業です。販売は０ですが、仕入れ・家賃などの支払いは発生します。';let m=month(state.turn);el('turnLabel').textContent=`第${fy(state.turn)}期 ${m}月 · TURN ${state.turn}`;el('headerCash').textContent=fmt(cash());el('ownerCash').textContent=fmt(state.owner);el('runway').textContent=`約${(cash()/675000).toFixed(1)}か月`;el('sceneSeason').textContent=[4,5,9,10].includes(m)?'釣りの繁忙期':[12,1,2].includes(m)?'冬の閑散期':'港町のいつもの一日';el('forecast').textContent=[4,5,9,10].includes(m)?'釣り需要が増加':[12,1,2].includes(m)?'来店客が少なめ':'通常の来店見込み';el('crowd').textContent=state.attraction>1.1?'にぎわい':state.attraction<.9?'閑散':'普通';el('orderAmount').textContent=fmt(orderCost());el('sideOrder').textContent='△'+fmt(orderCost());el('sideAction').textContent=actionCost()?'△'+fmt(actionCost()):'0千円';let after=cash()-orderCost()-actionCost();el('cashPreview').textContent=fmt(Math.max(0,after));el('previewDelta').textContent='仕入・行動の支払い後（販売前）';el('previewDelta').className='cash-change down';el('cashMeter').style.width=`${Math.min(100,Math.max(0,after/10000000*100))}%`;el('commit').disabled=after<0;el('commit').textContent=after<0?'預金が足りません · 仕入量を減らす':'今月を確定して月次報告を見る →';renderOrders();document.querySelectorAll('#prices button').forEach(b=>b.classList.toggle('active',b.dataset.value===choice.price));document.querySelectorAll('#actions button').forEach(b=>b.classList.toggle('active',b.dataset.value===choice.action));animateScene();renderTutorial()}
function closeMonth(){if(orderCost()+actionCost()>cash())return;const before={...state.balances},opening=before.預金,entries=[];const b={...before};const t=state.turn,m=month(t);let collected=0;state.receivables=state.receivables.filter(r=>{if(r.due<=t){journal(b,entries,'預金','売掛金',r.amount,'カード売上の回収');collected+=r.amount;return false}return true});const spend=orderCost();journal(b,entries,'商品','預金',spend,'今月の商品仕入');if(choice.action==='sales'){journal(b,entries,'広告宣伝費','預金',200000,'釣り大会を協賛');state.tournament=3}if(choice.action==='fixture'&&!state.fixture){journal(b,entries,'什器','預金',1000000,'什器を購入');state.fixture=true}let customers=Math.round(600*state.attraction*({4:1.15,5:1.25,6:1,7:1.05,8:1.1,9:1.15,10:1.25,11:1,12:.75,1:.65,2:.7,3:.95}[m])*(state.tournament?1.15:1));let capacity=choice.action==='tend'?350+(state.fixture?350:0):0;let served=Math.min(customers,capacity);let factor={list:[1,1],plus10:[1.1,.8],minus10:[.9,1.2],sale:[.8,1.5]}[choice.price];let cashSales=0,cardSales=0,cogs=0,waste=0;
products.forEach((p,i)=>{let purchased=choice.quantities[i];state.inventory[i]+=purchased;let count=state.inventory[i];let season=(i===2?([4,5,9,10].includes(m)?1.4:[12,1,2].includes(m)?.7:1):1);let demand=Math.round(served*p[3]*factor[1]*season);let sold=Math.min(count,Math.max(0,demand));let rev=Math.round(sold*p[2]*factor[0]);let cost=sold*p[1];state.inventory[i]-=sold;if(i<2)cashSales+=rev;else cardSales+=rev;cogs+=cost;if(i===1){waste=state.inventory[i]*p[1];state.inventory[i]=0}});journal(b,entries,'預金','売上高',cashSales,'店頭の現金売上');journal(b,entries,'売掛金','売上高',cardSales,'カード売上（２か月後入金）');if(cardSales)state.receivables.push({due:t+2,amount:cardSales});journal(b,entries,'売上原価','商品',cogs,'販売した商品の原価');journal(b,entries,'売上原価','商品',waste,'生エサの廃棄');journal(b,entries,'役員報酬','預金',300000,'役員報酬');journal(b,entries,'法定福利費','預金',45000,'社会保険の会社負担');journal(b,entries,'地代家賃','預金',t===1?0:150000,'店舗家賃');journal(b,entries,'広告宣伝費','預金',50000,'毎月の広告費');journal(b,entries,'雑費','預金',130000,'店舗の雑費');let dep=state.fixture?Math.floor(1000000/72):0;journal(b,entries,'減価償却費','減価償却累計額',dep,'什器の月割償却');const personal=settlePersonal(b,entries,t);state.balances=b;state.entries.push(...entries.map(e=>({...e,turn:t})));state.history.push({turn:t,balances:{...b}});state.attraction=Math.min(1.5,Math.max(.6,state.attraction+(choice.price==='sale'?.05:0)+(choice.action==='sales'?.08:0)-(choice.action==='tend'&&t>=4?.02:0)));if(state.tournament>0)state.tournament--;
const fixedCash=t===1?525000:675000;const inflow=cashSales+collected+personal.received,outflow=personal.lent+spend+(choice.action==='sales'?200000:choice.action==='fixture'&&!before.什器?1000000:0)+fixedCash;lastReport={personal,turn:t,fixedCash,before,after:{...b},opening,entries,inflow,outflow,cashSales,cardSales,collected,spend,extra:choice.action==='sales'?200000:choice.action==='fixture'&&!before.什器?1000000:0,served,customers,waste,action:choice.action,month:m,fy:fy(t),dep,monthProfit:accrued(b)-accrued(before)};monthClosed=true;tab='bs';saveGame();showNewEntries(entries)}
function accrued(b){return incomeAccounts.reduce((n,a)=>n+(b[a]||0),0)-expenseAccounts.reduce((s,a)=>s+(b[a]||0),0)}
function rowsForTB(r){let prev={...r.before},curr={...r.after};prev.当期損益=accrued(prev);curr.当期損益=accrued(curr);const groups=[['資産',assetAccounts],['負債・純資産',['資本金','繰越利益剰余金']],['損益',incomeAccounts.concat(expenseAccounts)]];let out='';for(const [title,accounts] of groups){out+=`<tr class="group"><td colspan="4">${title}</td></tr>`;for(const a of accounts){let v=curr[a]||0,old=prev[a]||0;if(!v&&!old)continue;let side=debitAccounts.includes(a)&&a!=='当期損益'?'debit':a==='当期損益'?(v>=0?'credit':'debit'):'credit';if(a==='減価償却累計額')side='credit';let debit=side==='debit'?Math.abs(v):0,credit=side==='credit'?Math.abs(v):0;out+=`<tr><td><button class="account" data-account="${a}">${a} ?</button></td><td>${debit?fmt(debit):'—'}</td><td>${credit?fmt(credit):'—'}</td><td class="${v-old>=0?'positive':'negative'}">${signed(v-old)}</td></tr>`}}let assets=assetAccounts.filter(a=>a!=='減価償却累計額').reduce((s,a)=>s+(curr[a]||0),0);let debitTotal=assets+expenseAccounts.reduce((s,a)=>s+(curr[a]||0),0);let creditTotal=(curr.資本金+curr.繰越利益剰余金+curr.売上高+(curr.減価償却累計額||0));if(curr.当期損益<0)debitTotal+=-curr.当期損益;else creditTotal+=curr.当期損益; // totals displayed from raw ledger below, without duplicated derived earnings
let rawDebit=assets+expenseAccounts.reduce((s,a)=>s+(curr[a]||0),0);let rawCredit=curr.資本金+curr.繰越利益剰余金+curr.売上高+(curr.減価償却累計額||0);out+=`<tr class="total"><td>借方・貸方合計</td><td>${fmt(rawDebit)}</td><td>${fmt(rawCredit)}</td><td>${rawDebit===rawCredit?'貸借一致':'要確認'}</td></tr>`;return `<table class="data"><thead><tr><th>勘定科目</th><th>借方残高</th><th>貸方残高</th><th>前月末からの増減</th></tr></thead><tbody>${out}</tbody></table>`}
function rowsForPL(r){let list=['売上高','売上原価','役員報酬','法定福利費','地代家賃','広告宣伝費','減価償却費','雑費'];let out=list.map(a=>{let now=r.after[a]-r.before[a];return `<tr><td><button class="account" data-account="${a}">${a} ?</button></td><td>${fmt(now)}</td><td>${fmt(r.after[a])}</td><td class="${now>0?'positive':'neutral'}">${signed(now)}</td></tr>`}).join('');return `<table class="data"><thead><tr><th>科目</th><th>今月</th><th>期首からの累計</th><th>今月の計上</th></tr></thead><tbody>${out}<tr class="total"><td><button class="account" data-account="当期損益">当期損益 ?</button></td><td>${fmt(r.monthProfit)}</td><td>${fmt(accrued(r.after))}</td><td>${signed(r.monthProfit)}</td></tr></tbody></table>`}
function renderReport(){const r=statementReport;el('reportTitle').textContent=`第${r.fy}期 ${r.month}月の月次報告`;el('reportCash').textContent=fmt(r.after.預金);let diff=r.after.預金-r.opening;el('reportCashDelta').textContent=`月初から ${signed(diff)}`;el('reportCashDelta').className='cash-change '+(diff<0?'down':'');el('headerCash').textContent=fmt(r.after.預金);el('ownerCash').textContent=fmt(state.owner);el('runway').textContent=`約${(cash()/675000).toFixed(1)}か月`;el('cashbar').innerHTML=`<span class="start" style="width:${Math.max(5,Math.min(85,r.opening/(r.opening+r.inflow)*100))}%"></span><span class="in" style="width:${Math.max(0,r.inflow/(r.opening+r.inflow)*100)}%"></span>`;el('cashExplanation').textContent=`税込売上代金 ${fmt(r.cashSales+r.cardSales)} のうち、カード ${fmt(r.cardSales)} は売掛金です。今月の預金には入りません。`;let flows=[['月初の預金',r.opening,''],['店頭の現金売上',r.cashSales,'positive'],['前月以前のカード売上回収',r.collected,'positive'],['商品の仕入',-r.spend,'negative'],['社長の行動',-r.extra,'negative'],['報酬・家賃・広告・その他',-r.fixedCash,'negative'],['役員への貸付',-(r.personal?.lent||0),'negative'],['役員から元利金回収',r.personal?.received||0,'positive'],['銀行・役員からの借入入金',r.borrowing||0,'positive'],['銀行への元金返済',-(r.debtService?.principal||0),'negative'],['銀行への支払利息',-(r.debtService?.interest||0),'negative'],['廃止商品の返品入金',r.retiredRefund||0,'positive'],['役員借入金の返済',-(r.ownerRepayment||0),'negative'],['法人税等の納付',-(r.tax?.paid||0),'negative'],['消費税の納付',-(r.consumption?.paid||0),'negative'],['消費税の還付',r.consumption?.refund||0,'positive'],['月末の預金',r.after.預金,'']];el('cashFlows').innerHTML=flows.map(([n,v,cl],i)=>`<div class="flowline"><span>${n}</span><b class="${cl}">${i===0||i===flows.length-1?fmt(v):signed(v)}</b></div>`).join('');el('resultChips').innerHTML=`${r.personal?.lent?`<span class="chip">生活費不足 → 役員貸付金 ＋${fmt(r.personal.lent)}・銀行審査に大幅マイナス</span>`:''}${r.after.未収利息?`<span class="chip">Q：利息未回収。税務調査で貸付条件・回収実態を確認されるリスクがあります</span>`:''}${r.personal?.unfunded?`<span class="chip">生活費未充足 ${fmt(r.personal.unfunded)}・会社にも立替余力がありません</span>`:''}<span class="chip">販売したお客 ${r.served}人</span><span class="chip">売り逃し ${Math.max(0,r.customers-r.served)}人</span><span class="chip">生エサ廃棄 ${fmt(r.waste)}</span><span class="chip">今月の損益 ${fmt(r.monthProfit)}</span>`;renderTable();renderTutorialReport()}
function renderTable(){if(tab==='trend'||tab==='bank'){el('reportTable').classList.add('bs-view');el('reportTable').innerHTML=tab==='trend'?renderTrends():renderBank();el('reportTable').setAttribute('aria-label',tab==='trend'?'連続決算書':'銀行審査');syncStatementChrome(null);return}renderComparisonControls();const r=activeFinancialReport();el('reportTable').classList.toggle('bs-view',tab==='bs');el('reportTable').innerHTML=(tab==='bs'?renderBS(r):tab==='tb'?rowsForTB(r):rowsForPL(r));el('reportTable').setAttribute('aria-label',`${r.annual?'年次決算書':'月次試算表'}、第${r.fy}期 ${r.month}月、単位は千円`);el('reportTable').scrollLeft=0;el('reportTable').scrollTop=0;document.querySelectorAll('.report-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));syncStatementChrome(r)}
function showHelp(a){const r=statementReport?activeFinancialReport():lastReport;let title=a==='game'?'この画面の使い方':a,body=a==='game'?'仕入量・値付け・社長の行動を決めて月末を確定します。販売と入金を仕訳し、毎月の資金増減と残高試算表を表示します。試作版では釣具店の基本行動に絞っています。':descriptions[a]||'';if(r&&a!=='game'){let delta=(a==='当期損益'?accrued(r.after)-accrued(r.before||{}):(r.after[a]||0)-((r.before||{})[a]||0));body+=` 今月の増減は ${signed(delta)}、月末残高は ${fmt(a==='当期損益'?accrued(r.after):r.after[a]||0)} です。`;let matches=r.entries.filter(e=>e.debit===a||e.credit===a).slice(0,4);if(matches.length)body+=` 関連する取引：${matches.map(e=>`${e.memo} ${fmt(e.amount)}`).join('／')}。`};if(r?.annual){body=body.replaceAll('今月','今期').replaceAll('月末残高','期末残高');if(!r.before)body=body.replace(/今期の増減は[^、]+、/,'前期の比較記録はなく、')}el('modalTitle').textContent=title;el('modalBody').textContent=body;el('modal').classList.add('open');el('closeModal').focus()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.closest('#orders')&&b.dataset.step!==undefined){const i=Number(b.dataset.product);setQuantity(i,Math.max(0,Math.min(100000,choice.quantities[i]+Number(b.dataset.step))))}else if(b.closest('#prices')){choice.price=b.dataset.value;renderPlanning()}else if(b.closest('#actions')){choice.action=b.dataset.value;renderPlanning()}else if(b.id==='reduceRod'){choice.quantities[2]=Math.floor(choice.quantities[2]/2);renderPlanning()}else if(b.id==='monthlyMode'){financialMode='month';renderTable()}else if(b.id==='annualMode'){financialMode='year';renderTable()}else if(b.id==='journalMenu'||b.id==='journalFromReport')openJournal();else if(b.id==='closeJournal')closeJournal();else if(b.id==='transactionNext')nextTransaction();else if(b.dataset.replay){replayEntry(Number(b.dataset.replay))}else if(b.id==='statementsMenu')openStatements();else if(b.id==='closeReport')closeStatements();else if(b.id==='commit'){if(monthClosed)advanceMonth();else closeMonth();}else if(b.id==='next'){advanceMonth()}else if(b.dataset.tab){tab=b.dataset.tab;renderTable()}else if(b.dataset.account)showHelp(b.dataset.account);else if(b.dataset.help)showHelp(b.dataset.help);else if(b.id==='closeModal')el('modal').classList.remove('open')});el('modal').addEventListener('click',e=>{if(e.target.id==='modal')el('modal').classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')el('modal').classList.remove('open')});renderPlanning();

let introStep=0;
const startupEntries=ShopEngine.STARTUP;
function introAdvance(){
 if(introStep<startupEntries.length){const entry=startupEntries[introStep];const entries=[];journal(state.balances,entries,entry.debit,entry.credit,entry.amount,entry.memo);const recorded={...entries[0],turn:1};state.entries.push(recorded);seenEntries.add(entryKey(recorded));introStep++;el('introCash').innerHTML=Math.round(state.balances.預金/1000).toLocaleString('ja-JP')+'<span> 千円</span>';el('introCapital').innerHTML=Math.round(state.balances.資本金/1000).toLocaleString('ja-JP')+'<span> 千円</span>';el('introJournal').innerHTML=transactionView(recorded);el('introTitle').textContent=['株式を払い込む','敷金を預ける','家賃を支払う','商品を仕入れる','最初の商品が売れた','売れた商品の原価を計上'][introStep-1];el('introSpeech').textContent=['会社の元手ができたで！これは売上やなくて資本金やな。','敷金を払ったで。お金は減るけど、預けた保証金が資産に残るんやな。','今月の家賃や。これは費用になるから、利益も減るんやな。','商品を仕入れたで！預金が商品に変わっただけで、まだ費用やないんやな。','最初のお客さんに売れたで！現金売上やから、その場で預金も増えるんや。','売れた分の仕入原価を費用にするんやな。残った商品は在庫として資産に残るで。'][introStep-1];el('introNext').textContent=['敷金を払い込む · 300千円 →','４月の家賃を払う · 150千円 →','商品を仕入れる · 1,500千円 →','最初の販売 · 1,000千円 →','売れた商品の原価を計上 · 600千円 →','よっしゃ、今月の経営を始めるで！ →'][introStep-1];el('introNote').textContent=`開業の取引 ${introStep} / ${startupEntries.length} · 光った科目が今回動いたところです。`;
 }else{introComplete=true;el('intro').classList.add('hidden');document.querySelector('.shell').inert=false;renderPlanning();saveGame();el('commit').focus()}
}
document.querySelector('.shell').inert=true;el('introNext').addEventListener('click',()=>introAdvance());
document.getElementById('orders').addEventListener('change',e=>{if(e.target.matches('input[data-product]'))setQuantity(Number(e.target.dataset.product),e.target.value)});

function advanceMonth(){if(!monthClosed)return;if(state.turn>=120){closeStatements();return}state.turn++;if(month(state.turn)===4){state.balances.繰越利益剰余金+=accrued(state.balances);for(const a of [...expenseAccounts,...incomeAccounts])state.balances[a]=0;}monthClosed=false;choice={quantities:[...choice.quantities],price:'list',action:'tend'};closeStatements();renderPlanning();saveGame();window.scrollTo({top:0,behavior:'smooth'})}
function openStatements(){financialMode='month';financialYear=Math.max(1,Math.floor((lastReport?.turn||0)/12));reportFocus=document.activeElement;statementReport=lastReport||{before:{...state.balances},after:{...state.balances},opening:cash(),entries:state.entries,inflow:0,outflow:0,cashSales:0,cardSales:0,collected:0,spend:0,extra:0,fixedCash:0,served:0,customers:0,waste:0,month:month(state.turn),fy:fy(state.turn),monthProfit:0};tab='bs';renderReport();el('reportTitle').textContent=lastReport?`第${lastReport.fy}期 ${lastReport.month}月末の決算書`:'開店時の決算書';el('monthlyDetails').hidden=!lastReport;el('next').hidden=!monthClosed;el('planning').inert=true;document.querySelector('.top').inert=true;el('report').classList.add('show');el('report').scrollTop=0;document.body.style.overflow='hidden';el('closeReport').focus();if(monthClosed)el('commit').textContent='次の月へ →'}
function closeStatements(){el('report').classList.remove('show');el('planning').inert=false;document.querySelector('.top').inert=false;document.body.style.overflow='';if(reportFocus?.focus)reportFocus.focus()}
function bsValues(b){const assets=assetAccounts.reduce((n,a)=>n+(a==='減価償却累計額'?-(b[a]||0):(b[a]||0)),0);const liabilities=['仮受消費税等','未払消費税等','買掛金','短期借入金','1年内返済予定長期借入金','長期借入金','未払法人税等','役員借入金','繰延売上','預り敷金'].reduce((n,a)=>n+(b[a]||0),0);const equity=(b.資本金||0)+(b.繰越利益剰余金||0)+accrued(b);return {assets,liabilities,equity}}
function renderBS(r){const b=r.after,old=r.before,v=bsValues(b);const nums=n=>n<0?'△'+Math.round(-n/1000).toLocaleString('ja-JP'):Math.round(n/1000).toLocaleString('ja-JP');const row=(a,n,prev)=>`<div class="bs-account"><button data-account="${a}">${a} <span>?</span></button><strong>${nums(n)}</strong><small class="${n-prev>0?'positive':n-prev<0?'negative':'neutral'}">${n===prev?'増減なし':signed(n-prev)}</small></div>`;
const subtotal=(name,value)=>`<div class="bs-subtotal"><span>${name}</span><b>${nums(value)}</b></div>`;
const category=(title,accounts)=>{let total=0;let content='';for(const a of accounts){let sign=a==='減価償却累計額'?-1:1;total+=sign*(b[a]||0);if(b[a]||old[a])content+=row(a,sign*(b[a]||0),sign*(old[a]||0))}return `<h4>${title}</h4>${content||'<p class="bs-empty">該当なし</p>'}${subtotal(title+'合計',total)}`};
const assets=category('流動資産',['預金','売掛金','商品','仮払消費税等','未収消費税等','仮払消費税中間納付','役員貸付金','未収利息','仮払法人税等','未収法人税等'])+category('固定資産',['土地','賃貸建物','船舶','車両','建物附属設備','什器','減価償却累計額','差入保証金']);
const liabilities=category('流動負債',['仮受消費税等','未払消費税等','買掛金','短期借入金','1年内返済予定長期借入金','未払法人税等'])+category('固定負債',['長期借入金','役員借入金','繰延売上','預り敷金'])+subtotal('負債合計',v.liabilities);
const equity=['資本金','繰越利益剰余金'].filter(a=>b[a]||old[a]).map(a=>row(a,b[a]||0,old[a]||0)).join('')+row('当期損益',accrued(b),accrued(old))+subtotal('純資産合計',v.equity);
const parts=[['預金',b.預金||0,'#217c9d'],['売掛金',b.売掛金||0,'#55b6c1'],['商品',b.商品||0,'#e6ae4c'],['その他資産',v.assets-(b.預金||0)-(b.売掛金||0)-(b.商品||0),'#8d9cb2']];const bars=parts.filter(p=>p[1]>0).map(([n,val,color])=>`<div title="${n} ${nums(val)}" style="height:${val/v.assets*100}%;background:${color}"></div>`).join('');
return `<div class="bs-equation"><b>資産 ${nums(v.assets)}</b><span>＝</span><b>負債・純資産 ${nums(v.liabilities+v.equity)}</b></div><div class="bs-visual"><div class="bs-stack">${bars}</div><div class="bs-visual-note">資金の運用<span>↔</span>資金の調達<br><small>同じ尺度で総額を比較</small></div><div class="bs-stack">${v.liabilities?`<div style="height:${v.liabilities/v.assets*100}%;background:#cb8062" title="負債"></div>`:''}<div style="height:${Math.max(0,v.equity/v.assets*100)}%;background:#287d69" title="純資産"></div></div></div><div class="bs-legend">${parts.filter(p=>p[1]>0).map(([n,val,c])=>`<span><i style="background:${c}"></i>${n}</span>`).join('')}<span><i style="background:#287d69"></i>純資産</span></div><div class="bs-sides"><section><h3>借方 · 資産の部</h3>${assets}</section><section><h3>貸方 · 負債・純資産</h3>${liabilities}<h4>純資産の部</h4>${equity}</section></div><div class="bs-totals"><div>資産合計<strong>${nums(v.assets)}</strong></div><div>負債・純資産合計<strong>${nums(v.liabilities+v.equity)}</strong></div></div><p class="bs-check">${v.assets===v.liabilities+v.equity?'✓ 貸借一致':'貸借不一致'} · 表示の端数は千円に丸めています。</p><p class="bs-footnote">左右は総額で対応します。例えば資本金がそのまま預金として残るとは限らず、商品や設備にも形を変えます。</p>`}
document.addEventListener('keydown',e=>{if(!el('report').classList.contains('show'))return;if(e.key==='Escape'&&!el('modal').classList.contains('open'))closeStatements();if(e.key==='Tab'&&!el('modal').classList.contains('open')){const focusable=[...el('report').querySelectorAll('summary,button:not([hidden]),select:not([hidden]),[tabindex="0"]')].filter(n=>n.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
// 設備資金の審査用。入力は同一年度の年間値（円）。マイナスも保持する。
function annualEquipmentRepaymentCapacity(annualOrdinaryProfit,annualDepreciation){return annualOrdinaryProfit+annualDepreciation;}

function lessonFor(t){return [
 ['売上と入金は、同じ月とは限らない','仕掛け・エサは現金売上。竿はカード売上で、今月売っても入金は２か月後です。仕入代金は先に預金から出ていきます。','売掛金'],
 ['売れた。でも、まだ入金待ち','先月のカード売上は今月も売掛金のまま。今月の仕入れや報酬を払えるだけの預金を残しましょう。','売掛金'],
 ['２か月前の売上が、預金に変わる','４月のカード売上が６月に入金されます。預金は増えますが、売上をもう一度計上するわけではありません。','預金'],
 ['在庫は、まだ現金に戻っていないお金','商品は資産ですが、支払いには使えません。残っている数量を見て、追加の仕入れが必要か考えましょう。','商品'],
 ['仕入れすぎると、廃棄も増える','エサは月末に売れ残りを廃棄します。売れなかった分の仕入代金も支払済みで、廃棄額は売上原価になります。','売上原価'],
 ['値下げと粗利の関係','値下げすると売れやすくなりますが、１個あたりの売上総利益は小さくなります。P/Lで売上と原価を比べましょう。','売上高'],
 ['売上が少なくても、支払いは続く','役員報酬・家賃などは販売が少ない月にも発生します。預金の余裕は、毎月の固定的な支払いと比べて考えましょう。','地代家賃'],
 ['資金調達は、足りなくなる前に考える','売掛金の回収より先に支払日が来ることがあります。仕入れを絞るだけでは足りないときは、入金予定と資金使途を整理して銀行への相談を検討します。借入金は売上にはなりません。','預金'],
 ['設備の購入代金と、毎月の費用','什器を買うと預金は購入代金だけ減ります。帳簿では固定資産になり、使う期間に分けて減価償却費を計上します。','減価償却費'],
 ['会社のお金と、社長のお金','役員報酬は会社の費用です。社長の生活費は個人預金から支払います。会社に残るお金と手元のお金を分けて見ましょう。','役員報酬'],
 ['利益が出ても、預金が減ることがある','売掛金や在庫が増えると、利益と預金の増減がずれます。P/LとB/S、資金の増減を一緒に確かめましょう。','当期損益'],
 ['１年の経営を、決算書で振り返る','資産の中身、資金の調達元、１年の損益を確認しましょう。来期の仕入れや投資は、利益だけでなく支払いの予定も踏まえて決めます。','当期損益']
 ][t-1]}
function learningHeader(t,title){return `<div class="learning-heading"><img src="assets/characters/q.png" alt="Q"><div><small>１年目の経営レッスン · ${t} / 12</small><h3>${title}</h3></div></div>`}
function renderTutorial(){const target=el('tutorialPlanning'),t=state.turn;target.hidden=t>12;if(t>12)return;const [title,description,account]=lessonFor(t);const spend=orderCost(),rod=choice.quantities[2]*products[2][1],fixed=t===1?525000:675000;const cashAfter=cash()-spend-actionCost()-fixed;const due=turn=>state.receivables.filter(x=>x.due===turn).reduce((v,x)=>v+x.amount,0);const recoverNow=due(t);const recoverNext=due(t+1);const recoverLater=due(t+2);const lessonMonth=month(t);const pressure=cashAfter<0?'予定した支払いが預金を上回っています。仕入量を見直し、追加資金が必要か確認しましょう。':cashAfter<fixed*2?'支払い後の余裕が小さくなっています。入金予定を確かめ、仕入れの削減や資金調達を早めに検討しましょう。':'今は支払える預金があります。竿を増やしたとき、入金より先にいくら出ていくか試してみましょう。';
 target.innerHTML=learningHeader(t,title)+`<p>${description}</p><div class="payment-timeline"><div><b>今月 ${lessonMonth}月</b><span class="negative">仕入支払 △${fmt(spend)}</span><small>うち竿 △${fmt(rod)}</small></div><div><b>来月 ${month(t+1)}月</b><span>今月の竿代は入金待ち</span></div><div><b>２か月後 ${month(t+2)}月</b><span class="positive">今月売れた竿の代金が入金</span></div></div><div class="receivable-schedule"><b>確定済みのカード入金予定</b><span>今月 ${fmt(recoverNow)} ／ 来月 ${fmt(recoverNext)} ／ 再来月 ${fmt(recoverLater)}</span></div><div class="learning-budget"><span>仕入・行動・固定的支払いの後</span><b class="${cashAfter<0?'negative':''}">${fmt(cashAfter)}</b><small>今月の販売・回収による入金を含めない目安</small></div><p class="learning-advice">${pressure}</p><div class="learning-actions"><button id="reduceRod" ${choice.quantities[2]===0?'disabled':''}>竿の仕入れを半分にして比べる</button><button data-help="${account}">科目の説明</button></div>`;
}
function renderTutorialReport(){const target=el('tutorialReport'),r=statementReport,t=r?.turn;target.hidden=!t||t>12;if(!t||t>12)return;const [title,description,account]=lessonFor(t);const delta=r.after.預金-r.before.預金;const arDelta=r.after.売掛金-r.before.売掛金;let detail='';if(t<=2){detail=`今月の売上 ${fmt(r.cashSales+r.cardSales)} のうち、カード売上 ${fmt(r.cardSales)} は ${month(t+2)}月入金です。仕入れの ${fmt(r.spend)} は今月支払済みです。`;}else if(t===3){detail=`４月のカード売上から ${fmt(r.collected)} を回収しました。仕訳は「預金／売掛金」。６月の売上には含めません。`;}else if(t===4){detail=`月末の商品は ${fmt(r.after.商品)}。仕入れた商品が売れるまで、その分のお金は在庫になっています。`;}else if(t===5){detail=`今月のエサ廃棄は ${fmt(r.waste)}。販売に結びつかなかった分も売上原価に含まれます。`;}else if(t===9){detail=`今月の什器購入支出は ${fmt(r.action==='fixture'?r.extra:0)}、減価償却費は ${fmt(r.dep)} です。`;}else{detail=description;}
 target.innerHTML=learningHeader(t,t===12?'１年目の振り返り':title)+`<p>${detail}</p><div class="learning-results"><div><small>預金の増減</small><b class="${delta<0?'negative':'positive'}">${signed(delta)}</b></div><div><small>売掛金の増減</small><b>${signed(arDelta)}</b></div><div><small>今月の損益</small><b class="${r.monthProfit<0?'negative':'positive'}">${fmt(r.monthProfit)}</b></div></div><p class="learning-advice">${r.monthProfit>0&&delta<0?'利益はプラスでも預金は減りました。売掛金・商品・設備の増加と支払いを見比べましょう。':t===12?'次の月からは通常の経営へ。決算書と入金予定を判断に使いましょう。':'この下のB/Sと資金の増減で、取引がどこに残ったか確認しましょう。'}</p><button class="learning-link" data-account="${account}">今回の科目を確認する →</button>`;
}

function entryKey(e){return e.debit+'|'+e.credit+(e.memo.includes('廃棄')?'|廃棄':'')}
function accountShift(e,a){return (e.after[a]||0)-(e.before[a]||0)}
function transactionView(e){const before=e.before,after=e.after,v=bsValues(after);const changes=[...new Set([e.debit,e.credit])];const fmtN=n=>n<0?'△'+fmt(-n):fmt(n);const cell=(a,value,prior)=>`<div class="motion-account ${value!==prior?'changed':''}"><span>${a}</span><b>${fmtN(value)}</b>${value!==prior?`<small>${fmtN(prior)} → ${fmtN(value)} <em class="${value-prior<0?'negative':'positive'}">${signed(value-prior)}</em></small>`:''}</div>`;const assetRows=assetAccounts.filter(a=>after[a]||before[a]).map(a=>cell(a,(a==='減価償却累計額'?-1:1)*(after[a]||0),(a==='減価償却累計額'?-1:1)*(before[a]||0))).join('');const rightRows=['資本金','繰越利益剰余金'].filter(a=>after[a]||before[a]).map(a=>cell(a,after[a]||0,before[a]||0)).join('')+cell('当期損益',accrued(after),accrued(before));const plRows=['売上高',...expenseAccounts].filter(a=>after[a]||before[a]).map(a=>cell(a,after[a]||0,before[a]||0)).join('')||'<p class="no-pl">売上・費用への影響なし</p>';const cashDiff=accountShift(e,'預金');const profitDiff=accrued(after)-accrued(before);
return `<div class="entry-journal"><div><small>借方</small><b>${e.debit}</b><strong>${fmt(e.amount)}</strong></div><span>／</span><div><small>貸方</small><b>${e.credit}</b><strong>${fmt(e.amount)}</strong></div></div><div class="entry-arrow" aria-hidden="true">↓ 帳簿へ反映</div><div class="motion-bs"><section><h3>B/S · 資産</h3>${assetRows||'<p>0千円</p>'}<div class="motion-total">合計 ${fmtN(v.assets)}</div></section><section><h3>B/S · 負債・純資産</h3>${rightRows}<div class="motion-total">合計 ${fmtN(v.liabilities+v.equity)}</div></section></div><div class="motion-pl"><h3>P/L · 売上と費用</h3>${plRows}<div class="motion-total">当期損益 ${fmtN(accrued(after))}</div></div><div class="entry-result"><span>預金 ${cashDiff?signed(cashDiff):'変化なし'}</span><span>利益 ${profitDiff?signed(profitDiff):'変化なし'}</span></div>`;
}
function showNewEntries(entries){const keys=new Set(seenEntries);animationQueue=entries.filter(e=>{const key=entryKey(e);if(keys.has(key))return false;keys.add(key);return true});animationReturn=null;if(animationQueue.length)showTransaction();else openStatements()}
function showTransaction(){const e=animationQueue[0];seenEntries.add(entryKey(e));saveGame();el('transactionTitle').textContent=e.memo;el('transactionCount').textContent=animationReturn?'仕訳の動きを振り返る':`初めての取引 · あと${animationQueue.length}件`;el('transactionBody').innerHTML=transactionView(e);el('transactionNext').textContent=animationQueue.length>1?'次の初めての取引へ →':animationReturn?'仕訳ログへ戻る':'今月の決算書を見る →';document.querySelector('.shell').inert=true;el('journalOverlay').inert=true;el('transactionOverlay').hidden=false;document.body.style.overflow='hidden';el('transactionOverlay').scrollTop=0;el('transactionNext').focus()}
function nextTransaction(){animationQueue.shift();if(animationQueue.length){showTransaction();return}el('transactionOverlay').hidden=true;document.querySelector('.shell').inert=false;el('journalOverlay').inert=false;if(animationReturn){animationReturn=null;el('closeJournal').focus()}else openStatements()}
function recentJournalEntries(){const latest=Math.max(1,...state.entries.map(e=>e.turn));return state.entries.map((e,index)=>({...e,index})).filter(e=>e.turn>=Math.max(1,latest-5)&&e.turn<=latest)}
function openJournal(){const entries=recentJournalEntries(),turns=[...new Set(entries.map(e=>e.turn))].sort((a,b)=>b-a);el('journalMonth').innerHTML='<option value="all">直近６か月すべて</option>'+turns.map(t=>`<option value="${t}">第${fy(t)}期 ${month(t)}月</option>`).join('');el('journalMonth').value='all';el('journalRange').textContent=turns.length?`第${fy(turns.at(-1))}期 ${month(turns.at(-1))}月 〜 第${fy(turns[0])}期 ${month(turns[0])}月 · 単位：千円`:'まだ取引はありません';renderJournal();document.querySelector('.shell').inert=true;el('journalOverlay').hidden=false;document.body.style.overflow='hidden';el('closeJournal').focus()}
function renderJournal(){const selected=el('journalMonth').value;const entries=recentJournalEntries().filter(e=>selected==='all'||e.turn===Number(selected)).reverse();el('journalEntries').innerHTML=entries.map(e=>`<article class="log-entry"><div class="log-entry-heading"><small>第${fy(e.turn)}期 ${month(e.turn)}月 · #${e.index+1}</small><button data-replay="${e.index+1}">動きを見る</button></div><h3>${e.memo}</h3><div class="entry-journal"><div><small>借方</small><b>${e.debit}</b><strong>${fmt(e.amount)}</strong></div><span>／</span><div><small>貸方</small><b>${e.credit}</b><strong>${fmt(e.amount)}</strong></div></div></article>`).join('')||'<p>この期間の仕訳はありません。</p>'}
function closeJournal(){el('journalOverlay').hidden=true;document.querySelector('.shell').inert=false;document.body.style.overflow=el('report').classList.contains('show')?'hidden':'';if(el('report').classList.contains('show'))el('journalFromReport').focus();else el('journalMenu').focus()}
function replayEntry(index){const e=state.entries[index-1];if(!e)return;animationQueue=[e];animationReturn='journal';showTransaction()}
function saveGame(){if(!introComplete)return;try{localStorage.setItem('finance-game-v2',JSON.stringify({state,choice,lastReport,monthClosed,seen:[...seenEntries],introComplete:true}))}catch{}}
el('journalMonth').addEventListener('change',renderJournal);
document.addEventListener('keydown',e=>{const overlay=!el('transactionOverlay').hidden?el('transactionOverlay'):!el('journalOverlay').hidden?el('journalOverlay'):null;if(!overlay)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(overlay.id==='journalOverlay')closeJournal();return}if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button,select')].filter(n=>!n.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},true);


function amountText(n){return (n<0?'▲':'')+Math.round(Math.abs(n)/1000).toLocaleString('ja-JP')}
function changeText(n){return n===null?'—':n===0?'±0':(n>0?'＋':'▲')+Math.round(Math.abs(n)/1000).toLocaleString('ja-JP')}
function renderComparisonControls(){const completed=Math.floor((lastReport?.turn||0)/12);el('annualMode').disabled=completed===0;if(completed===0)financialMode='month';el('monthlyMode').classList.toggle('active',financialMode==='month');el('annualMode').classList.toggle('active',financialMode==='year');el('statementYear').hidden=financialMode!=='year';el('statementYear').innerHTML=Array.from({length:completed},(_,i)=>`<option value="${i+1}">第${i+1}期</option>`).join('');el('statementYear').value=String(financialYear);el('comparisonPeriod').textContent=financialMode==='year'?'金額・増減の単位：千円／前期末比':completed?'金額・増減の単位：千円／前月末比':'金額・増減の単位：千円／初月は開店時比。年次決算書は３月末から';document.querySelectorAll('[data-tab="tb"]').forEach(b=>b.hidden=financialMode==='year');if(financialMode==='year'&&tab==='tb')tab='bs'}
function activeFinancialReport(){if(financialMode!=='year')return statementReport;const t=financialYear*12;const end=state.history.find(x=>x.turn===t);const prev=state.history.find(x=>x.turn===t-12);return {after:end?.balances||{},before:prev?.balances||null,turn:t,month:3,fy:financialYear,entries:state.entries.filter(e=>e.turn>t-12&&e.turn<=t),annual:true}}
function syncStatementChrome(r){renderAccountingGuide(r);const summary=el('statementPeriodSummary');if(!r){summary.hidden=true;el('monthlyDetails').hidden=true;el('tutorialReport').hidden=true;el('reportTitle').textContent=tab==='bank'?'銀行審査':tab==='trend'?'連続決算書':'決算書';return;}if(r.annual){const prior=r.before?.預金;el('reportTitle').textContent=`第${r.fy}期 3月末・確定の決算書`;el('reportCash').textContent=fmt(r.after.預金||0);el('reportCashDelta').textContent=prior===undefined?'前期末の比較対象なし':`前期末から ${signed((r.after.預金||0)-prior)}`;summary.hidden=false;summary.innerHTML=`<b>第${r.fy}期末の会社預金 ${fmt(r.after.預金||0)}</b><span>${prior===undefined?'初年度・前年比なし':`前期末比 ${signed((r.after.預金||0)-prior)}`}</span>`;el('monthlyDetails').hidden=true;el('tutorialReport').hidden=true;el('comparisonPeriod').textContent=`第${r.fy}期の確定決算／B/Sは前期末比・P/L累計は前年同期比・単月は前月比／単位：千円`;return;}summary.hidden=true;el('comparisonPeriod').textContent='単位：千円／'+(tab==='pl'?'期首4月からの累計・前年同期比':tab==='pl-month'?'表示月の1か月分・前月比':'月末（未確定月は現在）の残高・前月末比');el('reportTitle').textContent=`第${r.fy}期 ${r.month}月${r.provisional?'・現在／未確定':'末・確定'}の試算表`;el('reportCash').textContent=fmt(r.after.預金||0);el('monthlyDetails').hidden=!!r.provisional;el('tutorialReport').hidden=!!r.provisional;}
function formalBalance(b,prior,label,animate=false,highlightAccounts=null){const value=(x,a)=>['当期損益','経常利益'].includes(a)?accrued(x):(a==='減価償却累計額'?-1:1)*(x[a]||0);const delta=(a)=>prior?value(b,a)-value(prior,a):null;const row=(name,val,d,type='item',account=null)=>{const direct=animate&&account&&highlightAccounts?.has(account)&&d!==null&&d!==0;return `<tr class="${type} ${direct?'ledger-highlight':''}"><th scope="row">${account&&!animate?`<button data-account="${account}">${name}</button>`:name}</th><td>${amountText(val)}</td><td class="${animate&&!direct?'neutral':d>0?'positive':d<0?'negative':'neutral'}">${changeText(d)}</td></tr>`};const section=(name,accounts)=>{let sum=0,old=0,rows='';for(const a of accounts){sum+=value(b,a);old+=prior?value(prior,a):0;if(value(b,a)||(prior&&value(prior,a)))rows+=row(a,value(b,a),delta(a),'item',a)}return row(name,sum,prior?sum-old:null,'category')+rows+row(name+'合計',sum,prior?sum-old:null,'subtotal')};const v=bsValues(b),pv=prior?bsValues(prior):null;
const left=section('流動資産',['預金','売掛金','商品','仮払消費税等','未収消費税等','仮払消費税中間納付','役員貸付金','未収利息','仮払法人税等','未収法人税等'])+section('固定資産',['土地','賃貸建物','船舶','車両','建物附属設備','什器','減価償却累計額','差入保証金']);const right=section('流動負債',['繰延売上','仮受消費税等','未払消費税等','買掛金','短期借入金','1年内返済予定長期借入金','未払法人税等'])+section('固定負債',['長期借入金','役員借入金','預り敷金'])+row('負債合計',v.liabilities,pv?v.liabilities-pv.liabilities:null,'subtotal')+section('純資産',['資本金','繰越利益剰余金','当期損益']);const table=(title,body,total)=>`<section class="formal-half"><h3>${title}</h3><table class="formal-table"><colgroup><col class="name-col"><col><col></colgroup><thead><tr><th>科目</th><th>金額</th><th>増減<small>${label}</small></th></tr></thead><tbody>${body}</tbody></table><table class="formal-table formal-total"><colgroup><col class="name-col"><col><col></colgroup><tbody>${total}</tbody></table></section>`;
return `<div class="formal-caption"><h2>貸借対照表</h2><span>単位：千円</span></div><div class="formal-balance">${table('資産の部',left,row('資産合計',v.assets,pv?v.assets-pv.assets:null,'total'))}${table('負債・純資産の部',right,row('負債・純資産合計',v.liabilities+v.equity,pv?v.liabilities+v.equity-pv.liabilities-pv.equity:null,'total'))}</div><p class="formal-foot">${v.assets===v.liabilities+v.equity?'貸借一致':'貸借不一致'}${prior?'':' ／ 比較対象の前期がないため、増減は「—」'}。金額は千円に丸めて表示。</p>`}
function renderBS(r){return formalBalance(r.after,r.annual?r.before:(r.previousClose||r.before),r.annual?'前期末比':r.turn===1||!r.turn?'開店時比':'前月末比')}
function plForTurns(start,end){const result=Object.fromEntries([...incomeAccounts,...expenseAccounts].map(a=>[a,0]));for(const e of state.entries.filter(e=>e.turn>=start&&e.turn<=end&&!e.type?.startsWith('yearClose.'))){if(e.debit in result)result[e.debit]+=incomeAccounts.includes(e.debit)?-e.amount:e.amount;if(e.credit in result)result[e.credit]+=incomeAccounts.includes(e.credit)?e.amount:-e.amount}return result}
function formalPL(b,prior,label,animate=false,cumulative=null,highlightAccounts=null){const fields=['売上高','売上原価','売上総利益',...expenseAccounts.filter(a=>a!=='売上原価'),'受取利息','経常利益','当期損益'];const val=(x,a)=>['当期損益','経常利益'].includes(a)?accrued(x):a==='売上総利益'?(x.売上高||0)-(x.売上原価||0):x[a]||0;const rows=fields.filter(a=>val(b,a)||(prior&&val(prior,a))||['売上総利益','当期損益'].includes(a)).map(a=>{const d=prior?val(b,a)-val(prior,a):null,direct=animate&&highlightAccounts?.has(a)&&d!==null&&d!==0;return `<tr class="${['当期損益','売上総利益'].includes(a)?'subtotal':''} ${direct?'ledger-highlight':''}"><th>${a}</th><td>${amountText(val(b,a))}</td><td class="${animate&&!direct?'neutral':d>0?'positive':d<0?'negative':'neutral'}">${changeText(d)}</td></tr>`}).join('');return `<div class="formal-caption"><h2>損益計算書</h2><span>単位：千円</span></div><table class="formal-table formal-pl"><thead><tr><th>科目</th><th>金額</th><th>増減<small>${label}</small></th></tr></thead><tbody>${rows}</tbody></table>`}
function rowsForPL(r){return renderPeriodPL(r)}
function renderPeriodPL(r){
 const t=r.turn||1,start=Math.floor((t-1)/12)*12+1,single=tab==='pl-month';
 const prior=single?(t>1?plForTurns(t-1,t-1):null):(start>12?plForTurns(start-12,t-12):null);
 const period=single?'P/L（単月）':'P/L（累計）';
 const range=single?('第'+r.fy+'期 '+r.month+'月'):('第'+r.fy+'期 4月〜'+r.month+'月');
 return '<p class="pl-period">'+period+' · '+range+(r.provisional?'（今月は未確定）':'（確定）')+'</p>'+formalPL(plForTurns(single?t:start,t),prior,single?'前月比':'前年同期比');
}
function journalAccounts(entries){const accounts=new Set();for(const e of entries){accounts.add(e.debit);accounts.add(e.credit);if(e.introVAT)accounts.add('仮払消費税等');}return accounts;}
function queAccountingLesson(kind,b=null,period='month'){
 const v=b?bsValues(b):null;
 const ratio=v&&v.assets>0?Math.round(v.equity/v.assets*1000)/10:null;
 const lessons={
  bs:{title:'B/S：今、会社に何がある？',lines:[
   'なになに？貸借対照表、通称バランスシート、B/Sか。これを見れば、<strong>基準日</strong>時点のワイの会社の資産と負債、それに純資産が分かるんやな！左側は会社が持ってる預金・商品・設備なんかの「資産」。右側は、その資産をどう用意したかを示すんや。',
   '右側は、借入金や未払いのお金みたいに支払う義務のある「負債」と、株主が出したお金や会社に残した利益の「純資産」。このゲームでは純資産を自己資本として見るで。左の資産合計と、右の負債・純資産合計は同じになるんやな！',
   ratio===100&&v.liabilities===0?'今んとこ、ワイが払い込んだお金だけで資産を用意してる。借金も未払いもないから、自己資本比率は100％や！これは会社の資産を、返す義務のない自己資本で何割まかなってるか、ちゅうことやな。払込後のお金は会社のもんで、ワイ個人の財布とは別やで。':'自己資本比率は「自己資本 ÷ 資産合計」。会社の資産を、返す義務のない自己資本で何割まかなってるかが分かるんや。'+(ratio===null?'':`この時点では${ratio}％やで。`),
   '仕訳の「借方」は左、「貸方」は右の名前や。借金したかどうかとは別なんやな。例えば株式払込なら、左の預金と右の資本金が同じ金額だけ増えるで。'
  ]},
  pl:{title:'P/L：この間に、いくらもうかった？',lines:[
   'こっちは損益計算書、P/Lか。'+(period==='cumulative'?'これは<strong>期首の4月から表示月までの累計</strong>や。':period==='year'?'これがワイの会社の<strong>1年間</strong>の成績表か！４月から翌年３月まで、どれだけもうかったかが分かるんやな。':'この月次P/Lがワイの会社の<strong>1か月間</strong>の成績表か！年次決算では<strong>1年間</strong>の成績表になるんやな。')+'売上などの「収益」から、商売にかかった「費用」を引いた残りが利益。マイナスなら赤字や。',
   '仕入れた商品は、売れた分だけ「売上原価」という費用になって、売れ残りはB/Sの資産に残るんや。売上から売上原価を引くと「売上総利益」、いわゆる粗利やな。そこから家賃や給料なんかを引いて、利息や税金まで計算した最後が「当期純利益」や。',
   '利益が出るとB/Sの純資産が増えて、赤字なら減る。でも利益と預金の増減は別やで。カード売上は今月の売上でも、入金は２か月後。売れたのに手元のお金が足らん、いうことも起こるんや！'
  ]},
  tb:{title:'試算表から決算書、そして税金の申告へ',lines:['これが試算表か。日々の取引を仕訳にして、科目ごとに集計した表なんやな。預金や借入の残高、売上や費用を確かめて、借方・貸方の合計が合ってるかも確認するんや。','こうして<strong>1年分の取引</strong>を集計して、在庫や減価償却、税金なんかの決算の整理をしたら、B/SやP/Lの決算書になるんやな。それをもとに<strong>税金の申告</strong>をするんや！毎月ちゃんと帳簿をつけることが、年度末の決算につながるんやな。']},
  operations:{title:'粗利から、店を続ける費用を引く',lines:['商品を売って粗利が出ても、まだ全部がもうけやないんやな。家賃や給料も費用としてP/Lに入る。預金で払えばB/Sの預金が減って、費用の分だけ利益と純資産も減るんや。']},
  depreciation:{title:'減価償却は、お金が出ていかない費用',lines:['棚やレジは、使った分を毎月「減価償却費」にするんやな。P/Lには費用が出て、B/Sでは設備の帳簿上の価値が減る。でも代金は買うときに払ってるから、この仕訳で預金がもう一度減るわけやないで。']},
  inventory:{title:'仕入と費用は、タイミングが違う',lines:['仕入れた時点では「商品」という資産なんやな。売れた分だけ売上原価に変わって、売れ残りはB/Sに残る。買いすぎたら預金は減るけど、それがすぐ全部赤字になるわけやないんか。']},
  collection:{title:'入金しても、売上を二度は数えない',lines:['カード代金が入ったで！でも売上は売った月に数えてるから、今回は預金が増えて売掛金が減るだけや。もう一回もうかったわけやないんやな。']},
  borrowing:{title:'借入で預金は増えても、利益は増えない',lines:['預金は増えたけど、同じだけ借金も増えたんか。売上も利益も増えてへん。これから返すお金やな。資産合計が増えても自己資本は増えへん。資産と借金、両方を見る必要があるんや。']},
  repayment:{title:'元金返済と利息は別もの',lines:['元金の返済は、B/Sの預金と借入金が減る。利息の方はP/Lの費用になるんやな。利益が出てても、元金返済の分のお金は残しとかんと！借入金の減少表示は、返済が進んだという意味にもなるんや。']},
  waste:{title:'売れるはずの商品が損失になった',lines:['商品がダメになって、B/Sの資産が減ってP/Lの廃棄損になったんやな。今またお金を払ったんやなくて、前に払った仕入代が回収できんようになったんか……。']},
  yearClose:{title:'新年度になっても、去年の赤字は消えない',lines:['新年度のP/Lはゼロから始まるけど、去年の利益や赤字が消えたわけやないんやな。B/Sの「繰越利益剰余金」に引き継ぐんか。赤字ならここが減って、自己資本を減らすんや。資本金そのものが減るわけやないで。']},
  vat:{title:'消費税まで、もうけと思って使わない',lines:['このゲームでは税抜の売上・仕入と、消費税を分けて記録するんやな。受け取る分は「仮受消費税等」、仕入などで払う分は「仮払消費税等」。決算で差額を精算するから、受け取った分まで全部使うたら納付のとき困るで！']},
  owner:{title:'役員借入・役員貸付は、会社から見た名前',lines:['ワイが会社に貸したら「役員借入金」、会社からワイが借りたら「役員貸付金」。名前は会社から見た呼び方なんやな！個人の生活費を会社の経費にしてええわけやないで。','役員借入金は帳簿では負債のまま。このゲームの銀行審査では自己資本に加算されるんや。逆に役員貸付金は審査で資産価値や利益を厳しく補正されるで。']},
  tax:{title:'税金を数える月と、払う月は別',lines:['決算で法人税等を費用にして、まだ払ってへん分を「未払法人税等」にするんやな。後で納付するときは預金と未払が減るだけ。費用を二度数えんようになってるんか。']},
  reading:{title:'区分・増減・自己資本の読み方',lines:['預金や日々の商売で回る商品は「流動資産」、長く使う設備や店舗の保証金は「固定資産」や。借入のうち翌１年に返す予定の元金は「流動負債」に分けて、近い支払が見えるようにするんやな。','増減の色は、良い・悪いを決める色やないで。借入金が減るのは返済が進んだ結果かもしれん。どの取引で変わったんかまで見るんや。','資本金は払い込んだ元手。自己資本には会社に残った利益や損失も含まれる。赤字になると、資本金が同じでも自己資本全体は減っていくんやな。']}
 };
 const lesson=lessons[kind];if(!lesson)return '';
 return `<aside class="que-accounting-lesson"><img src="assets/characters/que.png" alt="クエ"><div><b>クエのひとこと · ${lesson.title}</b>${lesson.lines.map(line=>`<p>${line}</p>`).join('')}</div></aside>`;
}
function transactionAccountingLesson(entries,b){
 if(entries.some(e=>e.type?.startsWith('yearClose.')))return queAccountingLesson('yearClose',b);
 if(entries.some(e=>e.debit==='預金'&&e.credit==='資本金'))return queAccountingLesson('bs',b);
 if(entries.some(e=>e.type==='collectCard'))return queAccountingLesson('collection',b);
 if(entries.some(e=>e.type?.startsWith('bankBorrow.')))return queAccountingLesson('borrowing',b);
 if(entries.some(e=>e.type?.startsWith('bankRepay.')||e.type==='bankInterest'))return queAccountingLesson('repayment',b);
 if(entries.some(e=>e.type?.startsWith('waste.')))return queAccountingLesson('waste',b);
 if(entries.some(e=>['ownerLoan','ownerFunding','ownerInterest','collectOwner','collectInterest'].includes(e.type)))return queAccountingLesson('owner',b);
 if(entries.some(e=>['taxAccrual','taxPayment'].includes(e.type)))return queAccountingLesson('tax',b);
 if(entries.some(e=>e.type==='loanReclass'))return queAccountingLesson('reading',b);
 if(entries.some(e=>['saleCash','saleCard','costOfSales'].includes(e.type)||e.credit==='売上高'))return queAccountingLesson('pl',b);
 if(entries.some(e=>e.type==='purchaseCash'))return queAccountingLesson('inventory',b);
 if(entries.some(e=>e.type==='depreciation'||e.debit==='減価償却費'))return queAccountingLesson('depreciation',b);
 if(entries.some(e=>['役員報酬','給料手当','地代家賃','法定福利費','広告宣伝費','雑費'].includes(e.debit)))return queAccountingLesson('operations',b);
 if(entries.some(e=>e.introVAT||e.type?.startsWith('vat')))return queAccountingLesson('vat',b);
 return '';
}
function renderAccountingGuide(r){
 const period=tab==='pl-month'?'month':tab==='pl'?'cumulative':r?.annual||tab==='trend'?'year':'month';
 const entries=r?.entries||[],topic=entries.some(e=>e.type?.startsWith('bankBorrow.'))?'borrowing':entries.some(e=>e.credit==='売掛金'&&e.debit==='預金')?'collection':entries.some(e=>e.type?.startsWith('waste.'))?'waste':'pl';
 const more=['inventory','collection','borrowing','repayment','waste','yearClose','vat','owner','tax','reading'];
 el('accountingBasicsBody').innerHTML=['tb','bs','pl'].map(kind=>`<details ${kind===topic?'open':''}><summary>${{tb:'試算表とは',bs:'B/S：資産・負債・純資産',pl:'P/L：売上から利益まで'}[kind]}</summary>${queAccountingLesson(kind,null,period)}</details>`).join('')+more.map(kind=>`<details ${kind===topic?'open':''}><summary>${{inventory:'仕入と売上原価',collection:'売掛金の回収',borrowing:'銀行から借りる',repayment:'元金と利息',waste:'在庫の廃棄',yearClose:'決算と翌期への繰越',vat:'消費税',owner:'社長と会社の貸し借り',tax:'法人税等の計上と納付',reading:'帳票の区分・増減・自己資本'}[kind]}</summary>${queAccountingLesson(kind)}</details>`).join('');
 const meaning=el('statementMeaning');meaning.hidden=!r;
 if(!r)return;
 const point=`<strong>基準日</strong>・第${r.fy}期 ${r.month}月${r.provisional?'の現在':'末'}`;
 const bs=`「B/Sを見れば、${point}時点のワイの会社の資産と負債、それに純資産が分かるんやな！」`;
 const pl=tab==='pl-month'?('「これは<strong>'+r.month+'月だけ</strong>の成績表や。前月と比べられるで。」'):'「これは<strong>期首の4月から'+r.month+'月までの累計</strong>や。前年の同じ期間と比べられるで。」';const tb='「試算表は、仕訳を科目ごとに集計して、残高や貸借の一致を確かめる表なんやな。<strong>1年分の取引</strong>を集計して決算の整理をしたら決算書になる。それをもとに<strong>税金の申告</strong>をするんや！」';
 meaning.innerHTML=`クエ ${tab==='bs'?bs:['pl','pl-month'].includes(tab)?pl:tb}`;
}
function transactionView(e){const accounts=journalAccounts([e]);return `<div class="entry-journal"><div><small>借方</small><b>${e.debit}</b><strong>${fmt(e.amount)}</strong></div><span>／</span><div><small>貸方</small><b>${e.credit}</b><strong>${fmt(e.amount)}</strong></div></div><p>黄色は仕訳の借方・貸方にある科目。合計や利益の増減はその結果です。</p><div class="entry-arrow">↓ 帳簿へ反映</div>${transactionAccountingLesson([e],e.after)}${formalBalance(e.after,e.before,'今回の取引',true,accounts)}${formalPL(e.after,e.before,'今回の取引',true,null,accounts)}`}
el('statementYear').addEventListener('change',e=>{financialYear=Number(e.target.value);renderTable()});
function rowsForTB(r){return formalBalance(r.after,r.before,r.turn===1?'開店時比':'前月末比').replace('貸借対照表','月次残高試算表')+rowsForPL(r)}

function renderPersonal(){el('livingCost').value=200;el('livingCost').disabled=true;el('payInterest').checked=state.payInterest!==false;el('repayOwner').checked=!!state.repayOwner;el('personalStatus').textContent=`役員貸付金 ${fmt(state.balances.役員貸付金||0)} ／ 未収利息 ${Math.round(state.balances.未収利息||0).toLocaleString()}円。役員貸付の純資産比率5％未満は−10点、20％未満は−25点、それ以上は−40点。`;}
function settlePersonal(b,entries,t){state.owner+=240000;const living=(state.livingCost??200)*1000;const needed=Math.max(0,living-state.owner);const lent=Math.min(needed,Math.max(0,b.預金));journal(b,entries,'役員貸付金','預金',lent,'生活費不足を会社から借入（１年以内返済の約定）');state.owner+=lent-living;let interest=Math.round((b.役員貸付金||0)*.013/12);journal(b,entries,'未収利息','受取利息',interest,'役員貸付の約定利息・ゲーム設定 年1.3％');let paid=state.payInterest===false?0:Math.min(Math.max(0,state.owner),b.未収利息||0);journal(b,entries,'預金','未収利息',paid,'役員が会社へ利息を支払う');state.owner-=paid;let principal=state.repayOwner?Math.min(Math.max(0,state.owner),b.役員貸付金||0):0;journal(b,entries,'預金','役員貸付金',principal,'役員貸付金を個人資金から返済');state.owner-=principal;return {lent,received:paid+principal,interest,paid,unfunded:Math.max(0,-state.owner)};}
function annualSeries(){return state.history.filter(h=>h.turn%12===0).map(h=>({year:h.turn/12,b:h.balances,p:plForTurns(h.turn-11,h.turn)}));}
function renderTrends(){const all=annualSeries(),years=all.slice(-3);if(!years.length)return '<div class="bank-review"><h2>連続決算書</h2><p>最初の３月決算後から表示します。月次試算表は今から確認できます。</p></div>';const value=(y,a)=>{const b=y.b,p=y.p,v=bsValues(b);return a==='流動資産合計'?['預金','売掛金','商品','仮払消費税等','未収消費税等','仮払消費税中間納付','役員貸付金','未収利息'].reduce((n,k)=>n+(b[k]||0),0):a==='固定資産合計'?ShopEngine.managementRatios(b).fixedAssets:a==='資産合計'?v.assets:a==='負債合計'?v.liabilities:a==='純資産合計'?v.equity:a==='売上総利益'?(p.売上高||0)-(p.売上原価||0):a==='経常利益'?ShopEngine.ordinary(p):a==='当期損益'?accrued(p):a==='年間弁済可能額'?ShopEngine.ordinary(p)+(p.減価償却費||0):a in p?p[a]:b[a]||0};const group=(title,fields)=>`<tr class="trend-group"><th>${title}</th>${years.map(()=>'<td></td>').join('')}</tr>`+fields.map(a=>`<tr><th scope="row">${a}</th>${years.map(y=>{const prev=all.find(z=>z.year===y.year-1),d=prev?value(y,a)-value(prev,a):null;return `<td>${amountText(value(y,a))}<small class="${d<0?'negative':d>0?'positive':''}">増減 ${changeText(d)}</small></td>`}).join('')}</tr>`).join('');return `<div class="formal-caption"><h2>連続決算書 · 直近３期</h2><span>単位：千円／前年比</span></div><p>確定した年度だけを比較。B/Sは各期末、P/Lは各期12か月。横スクロールしても科目名は固定です。</p><div class="trend-scroll" tabindex="0"><table class="trend-table"><thead><tr><th>科目</th>${years.map(y=>`<th>第${y.year}期<small>４月〜３月</small></th>`).join('')}</tr></thead><tbody>${group('B/S 資産',['預金','売掛金','商品','仮払消費税等','未収消費税等','仮払消費税中間納付','役員貸付金','未収利息','流動資産合計','土地','賃貸建物','船舶','車両','建物附属設備','什器','減価償却累計額','差入保証金','固定資産合計','資産合計'])}${group('B/S 負債・純資産',['短期借入金','1年内返済予定長期借入金','長期借入金','役員借入金','繰延売上','預り敷金','仮受消費税等','未払消費税等','未払法人税等','負債合計','資本金','繰越利益剰余金','純資産合計'])}${group('P/L',['売上高','売上原価','売上総利益',...expenseAccounts.filter(a=>a!=='売上原価'),'受取利息','経常利益','当期損益','年間弁済可能額'])}</tbody></table></div>`;}

function bankAssessment(series,b){
 const bookEquity=bsValues(b).equity,ownerDebt=b.役員借入金||0,ownerLoss=b.役員貸付金||0;
 b={...b,役員借入金:0,役員貸付金:0,繰越利益剰余金:(b.繰越利益剰余金||0)+ownerDebt-ownerLoss};

 const latest=series.at(-1),p=latest?.p||{},v=bsValues(b),sales=p.売上高||0;
 const operating=sales-ownerLoss-expenseAccounts.filter(k=>!['支払利息','法人税等'].includes(k)).reduce((n,k)=>n+(p[k]||0),0),ordinary=ShopEngine.ordinary(p)-ownerLoss,dep=p.減価償却費||0;
 const capacity=latest?Math.floor(series.slice(-2).reduce((n,y)=>n+ShopEngine.ordinary(y.p)+(y.p.減価償却費||0),0)/Math.min(2,series.length))-ownerLoss:null;
 const debt=Math.max(0,b.短期借入金||0)+Math.max(0,b.長期借入金||0)+Math.max(0,b['1年内返済予定長期借入金']||0)+Math.max(0,b.役員借入金||0);
 const currentDebt=['仮受消費税等','未払消費税等','買掛金','短期借入金','1年内返済予定長期借入金','未払法人税等'].reduce((n,k)=>n+Math.max(0,b[k]||0),0);
 const liquid=Math.max(0,b.預金||0)+Math.max(0,b.売掛金||0),working=Math.max(0,(b.売掛金||0)+(b.商品||0)-(b.買掛金||0));
 const equityRatio=v.assets>0?v.equity/v.assets:null,margin=latest&&sales>0?operating/sales:null;
 const debtYears=!latest?null:debt===0?0:capacity>0?Math.max(0,debt-Math.min(b.短期借入金||0,working))/capacity:Infinity;
 const netDebtYears=!latest?null:operating+dep>0?(debt-(b.預金||0))/(operating+dep):null;
 const quick=currentDebt>0?liquid/currentDebt:liquid>0?Infinity:null;
 const cycle=latest&&sales>0?working/(sales/12):null;
 const recent=series.slice(-3),growths=recent.slice(1).map((y,i)=>{const prev=recent[i].p.売上高||0;return prev>0?(y.p.売上高||0)/prev-1:null}).filter(x=>x!==null);
 const growth=growths.length?growths.reduce((n,x)=>n+x,0)/growths.length:null;
 const high=(x,bands)=>x===null?null:bands.find(([threshold])=>x>=threshold)?.[1]??0;
 const low=(x,bands)=>x===null?null:bands.find(([threshold])=>x<=threshold)?.[1]??0;
 const percent=x=>x===null?'算定不可':(x*100).toFixed(1)+'％';
 const multiple=x=>x===null?'算定不可':x===Infinity?'返済原資不足':x.toFixed(1)+'年';
 const safety=ShopEngine.managementRatios(b);
 const metrics=[
 {name:'自己資本比率',value:percent(equityRatio),formula:'（帳簿純資産＋役員借入金−役員貸付金）÷（帳簿総資産−役員貸付金）',max:20,points:high(equityRatio,[[.4,20],[.2,16],[.1,10],[0,4]]),rule:'40％以上20点／20％以上16点／10％以上10点／0％以上4点／負数0点'},
 {name:'債務償還年数',value:multiple(debtYears),formula:'（借入金−正常運転資金に対応する短期借入）÷ 直近最大２期平均の年間弁済可能額',max:20,points:latest?(capacity<=0?0:low(debtYears,[[3,20],[5,16],[10,10],[15,4]])):null,rule:'3年以下20点／5年以下16点／10年以下10点／15年以下4点／超過・返済原資不足0点'},
 {name:'営業利益率',value:percent(margin),formula:'（営業利益−役員貸付金残高の損失補正）÷ 売上高',max:15,points:high(margin,[[.05,15],[.03,12],[.01,9],[0,4]]),rule:'5％以上15点／3％以上12点／1％以上9点／0％以上4点／赤字0点'},
 {name:'流動比率',value:safety.currentRatio===Infinity?'流動負債なし':percent(safety.currentRatio),formula:'流動資産 ÷ 流動負債。審査時は役員貸付金を除外',max:10,points:high(safety.currentRatio,[[2,10],[1.5,8],[1,5],[.8,2]]),rule:'200％以上10点／150％以上8点／100％以上5点／80％以上2点／未満0点'},
 {name:'固定長期適合率',value:percent(safety.fixedLongRatio),formula:'固定資産 ÷（自己資本＋固定負債）。審査用補正後の数値',max:10,points:safety.fixedLongRatio===null?0:low(safety.fixedLongRatio,[[.7,10],[1,8],[1.2,4]]),rule:'70％以下10点／100％以下8点／120％以下4点／超過・長期資金が０以下は0点'},
 {name:'当座比率',value:quick===Infinity?'流動負債なし':percent(quick),formula:'（預金＋売掛金）÷ 流動負債。商品・役員貸付金は除外',max:10,points:high(quick,[[1.5,10],[1,8],[.7,4]]),rule:'150％以上10点／100％以上8点／70％以上4点／未満0点'},
 {name:'営業運転資本回転期間',value:cycle===null?'算定不可':cycle.toFixed(1)+'か月',formula:'（売掛金＋商品−買掛金）÷ 月商。負の運転資本は0として採点',max:5,points:low(cycle,[[1,5],[2,4],[3,3],[6,1]]),rule:'1か月以下5点／2か月以下4点／3か月以下3点／6か月以下1点／超過0点'},
 {name:'売上高増加率',value:percent(growth),formula:'（当期売上÷前期売上−1）の直近最大2区間平均',max:10,points:high(growth,[[.1,10],[0,8],[-.05,5],[-.15,2]]),rule:'10％以上10点／0％以上8点／−5％以上5点／−15％以上2点／未満0点'}
 ];
 const scored=metrics.filter(m=>m.points!==null),possible=scored.reduce((n,m)=>n+m.max,0),raw=scored.reduce((n,m)=>n+m.points,0);
 const financialScore=latest&&possible?Math.round(raw/possible*100):null;let adjustment=0,reasons=[];
 const penalize=(points,reason)=>{adjustment-=points;reasons.push(reason+'：−'+points+'点（ゲーム内補正）')};
 if(recent.length>=3&&recent.slice(1).every((y,i)=>ShopEngine.ordinary(y.p)<ShopEngine.ordinary(recent[i].p)))penalize(10,'経常利益が２期連続で悪化');
 if(ownerLoss>0)penalize(bookEquity<=0||ownerLoss/bookEquity>=.2?40:ownerLoss/bookEquity>=.05?25:10,'役員貸付金の純資産比率に応じた資金分離の評価');
 if((b.未収利息||0)>0)penalize(10,'役員貸付利息の回収管理に問題');
 if(series.length<3)reasons.push('業歴３期未満の格付けはBが上限（ゲーム設定）');if(!reasons.length)reasons.push('定性・トレンド補正なし');
 reasons.push('審査上の自己資本に役員借入金を加算：'+fmt(ownerDebt)+'／役員貸付金の損失補正：'+fmt(ownerLoss)+'。帳簿の利益は変更しません。');
 const score=financialScore===null?null:Math.max(0,Math.min(100,financialScore+adjustment));
 const terms=bankTerms(score===null?null:series.length<3?Math.min(score,79):score,capacity,b);
 const verdict=score===null?'通期実績不足・創業計画の審査が必要':!terms.eligible?'ゲーム内判定：融資不可':terms.short.available>0||terms.equipment.available>0?'ゲーム内判定：融資可能':'追加融資余力なし';
 return {bookEquity,adjustedEquity:v.equity,ownerDebt,ownerLoss,adjustedOrdinary:ordinary,score,financialScore,raw,possible,adjustment,metrics,reasons,capacity,verdict,netDebtYears,period:latest?'直近確定年度のP/L ＋ 現在のB/S':'通期P/L未確定',...terms};
}
function bankEvidence(a){return `<h3>財務指標からの採点</h3><p>${a.period}。金額は円単位で計算。</p><div class="credit-rules"><table><thead><tr><th>指標</th><th>実績</th><th>得点</th></tr></thead><tbody>${a.metrics.map(m=>`<tr><th>${m.name}</th><td>${m.value}</td><td>${m.points===null?'対象外':m.points+' / '+m.max}</td></tr>`).join('')}</tbody></table></div><p>財務評価 ${a.financialScore===null?'未確定':a.financialScore+'点'}（${a.raw} / ${a.possible} を100点換算）＋ 定性・トレンド補正 ${a.adjustment}点。算定できない指標は０点とせず対象外。ただし通期決算なしでは総合点を確定しません。</p><p>参考：EBITDA有利子負債倍率 ${a.netDebtYears===null?'算定不可':a.netDebtYears.toFixed(1)+'倍'}＝（借入金−預金）÷（営業利益＋減価償却費）。上の債務償還年数とは別の指標です。預金が借入金を上回れば負数になります。</p><details><summary>算式・採点区分と実務資料</summary>${a.metrics.map(m=>`<p><b>${m.name}</b><br>${m.formula}<br>${m.rule}</p>`).join('')}<p>指標は公庫・ローカルベンチマーク等の公開資料を参考に採用。上記の配点・境界値は学習用で、公式ロカベン評点や銀行・CRDのモデルを再現したものではありません。同業小売業との統計比較、担保・保証、返済履歴、事業計画の個別審査は未実装です。</p><ul><li><a href="https://www.jfc.go.jp/n/service/pdf/keieikaizentebiki_190801n.pdf" target="_blank" rel="noopener">日本政策金融公庫：経営改善計画書策定の手引</a>（返済原資・債務償還年数・資産内容）</li><li><a href="https://www.meti.go.jp/policy/economy/keiei_innovation/sangyokinyu/locaben/index.html" target="_blank" rel="noopener">経済産業省：ローカルベンチマーク</a>（利益率・成長・安全性・運転資本）</li><li><a href="https://www.crd-office.net/CRD/service/scoring/index.html" target="_blank" rel="noopener">CRD協会：スコアリングサービス</a>（統計的な信用リスク評価。実モデルには未接続）</li><li><a href="https://www.fsa.go.jp/common/paper/25/zentai/03.pdf" target="_blank" rel="noopener">金融庁：経営者保証ガイドラインQ&A概要</a>（法人と経営者の資金分離。比率に応じた減点はゲーム設定）</li></ul></details>`;}

function bankTerms(score,capacity,b){
 const tier=score>=80?{grade:'A',rate:2,coverage:1,years:10}:score>=65?{grade:'B',rate:3,coverage:.8,years:7}:score>=50?{grade:'C',rate:5,coverage:.5,years:5}:{grade:'D',rate:null,coverage:0,years:0};
 const eligible=score!==null&&score>=50&&bsValues(b).equity>0&&(b.預金||0)>=0;
 const workingNeed=Math.max(0,(b.売掛金||0)+(b.商品||0)-(b.買掛金||0));
 const shortBalance=Math.max(0,b.短期借入金||0),equipmentBalance=Math.max(0,(b.長期借入金||0)+(b['1年内返済予定長期借入金']||0));
 const shortLimit=eligible?Math.floor(workingNeed*tier.coverage):0;
 const equipmentCeiling=Math.max(0,capacity||0)*10;
 const equipmentLimit=eligible?Math.floor(Math.max(0,capacity||0)*tier.years):0;
 const facility=(limit,balance)=>({limit,balance,available:Math.max(0,limit-balance),excess:Math.max(0,balance-limit)});
 return {eligible,grade:score===null?'未格付':tier.grade,rate:eligible?tier.rate:null,coverage:tier.coverage,years:tier.years,workingNeed,equipmentCeiling,short:facility(shortLimit,shortBalance),equipment:facility(equipmentLimit,equipmentBalance)};
}
function renderBank(){const a=bankAssessment(annualSeries(),state.balances);const card=(name,f,why)=>`<section class="credit-facility"><h3>${name}</h3><p class="credit-status">${a.score===null?'審査保留':!a.eligible?'融資不可':f.available>0?'追加融資可':f.limit>0?'枠を利用中':'新規融資不可'}</p><dl><div><dt>融資限度額（総枠）</dt><dd>${fmt(f.limit)}</dd></div><div><dt>既存借入残高</dt><dd>${fmt(f.balance)}</dd></div><div class="credit-available"><dt>追加で借りられる額</dt><dd>${fmt(f.available)}</dd></div><div><dt>新規融資の年利</dt><dd>${a.rate!==null&&f.limit>0?a.rate.toFixed(1)+'％':'—'}</dd></div></dl><p>${why}</p>${f.excess?`<p class="negative">枠超過 ${fmt(f.excess)}。追加融資不可。既存借入の残高・契約は変更しません。</p>`:''}</section>`;
return `<section class="bank-review"><h2>銀行審査 · 金利と融資枠</h2><p class="bank-verdict">${a.verdict} · ${a.score===null?'—':a.score} / 100</p><p>格付け <b>${a.grade}</b> ／ 新規融資の基準年利 <b>${a.rate===null?'適用なし':a.rate.toFixed(1)+'％'}</b></p><div class="credit-grid">${card('運転資金 · 短期枠',a.short,`必要運転資金 ${fmt(a.workingNeed)} × 掛目 ${(a.coverage*100).toFixed(0)}％。必要運転資金＝売掛金＋商品−買掛金（最低０）。役員貸付金は対象外。`)}${card('設備資金 · 長期枠',a.equipment,a.capacity===null?'通期決算が未確定のため、設備資金枠は０。最初の３月決算後に審査します。':`年間弁済可能額 ${fmt(a.capacity)} × ${a.years}年分。絶対上限は10年分 ${fmt(a.equipmentCeiling)}。弁済可能額が０以下なら融資不可。`)}</div><p>年間弁済可能額＝直近最大２期の「経常利益＋減価償却費」の平均。負数も表示し、融資枠は最低０とします。短期借入は短期枠、長期借入は設備枠からそれぞれ控除します。</p>${!annualSeries().length?'<p>創業初年度：通期実績がないため、この実績型スコアは審査保留。実務では創業計画・自己資金・経験なども確認します。創業融資の別審査は未実装です。</p>':''}<details><summary>スコア・金利・枠の基準を見る</summary><div class="credit-rules"><table><thead><tr><th>点数</th><th>格付け</th><th>年利</th><th>短期掛目</th><th>設備枠</th></tr></thead><tbody><tr><td>80〜100</td><td>A</td><td>2.0％</td><td>100％</td><td>弁済可能額×10年</td></tr><tr><td>65〜79</td><td>B</td><td>3.0％</td><td>80％</td><td>×7年</td></tr><tr><td>50〜64</td><td>C</td><td>5.0％</td><td>50％</td><td>×5年</td></tr><tr><td>0〜49</td><td>D</td><td>融資不可</td><td>０</td><td>０</td></tr></tbody></table></div><p>ゲームでは純資産が０以下、または預金が負の場合も新規融資を止めます。実務の一律の否決条件ではありません。各倍率は枠の計算基準で、返済期間を確約するものではありません。実際の設備融資額は設備代金も上限になります。</p></details>${bankEvidence(a)}<p>業歴３期未満はB格付けが上限。設備の返済期間・枠は、選んだ設備の償却期間以内にさらに制限します。</p><h3>定性・トレンド補正</h3><ul>${a.reasons.map(r=>`<li>${r}</li>`).join('')}</ul><p>実務の財務分析を参考にした学習モデル。配点・境界値・金利・掛目はゲーム設定で、実際の銀行格付けやデフォルト確率ではありません。金利はゲーム内の基準1.5％＋格付け別上乗せ0.5／1.5／3.5％。希望額を選んで審査後、契約内容を確認すると入金します。短期は12か月後に一括返済（前月から書き換え審査可）、設備は償却期間以内の元金均等で毎月返済。どちらも翌月から利息を支払います。</p><h3>Qの税務チェック</h3><p>${(state.balances.未収利息||0)>0?'利息が未回収です。約定どおりの回収や貸付条件を確認しましょう。':'現在、未回収の約定利息はありません。'}</p><p>生活費不足は「役員貸付金／預金」、利息発生は「未収利息／受取利息」。元本返済は利益になりません。会社の預金が足りない場合、個人預金のマイナスは生活費未充足額です。</p><p>ゲームでは年1.3％、月初残高で計算。無利息・低利の利益は原則給与課税ですが、年間の利息差額5,000円以下などの例外があります。未払いだけで自動的に追徴税額を発生させません。</p><a href="https://www.nta.go.jp/taxes/shiraberu/taxanswer/gensen/2606.htm" target="_blank" rel="noopener">国税庁：金銭を貸し付けたとき</a></section>`;}
['livingCost','payInterest','repayOwner'].forEach(id=>el(id).addEventListener('change',()=>{state=E.playerSettings(state,{livingCost:200,payInterest:el('payInterest').checked,repayOwner:el('repayOwner').checked});saveGame();renderPersonal()}));
